import {MONSTERS,Adventure,selectPool,makeOptions,scramble} from './engine.mjs';
import {IslandAudio,WordSpeaker,migrateAudioSettings} from './audio.mjs';
import {BattleAction} from './battle.mjs';
import {MonsterPark} from './park.mjs';
const $=s=>document.querySelector(s), app=$('#app'), modal=$('#modal');
const icon=(name,cls='')=>`<svg class="icon ${cls}" aria-hidden="true"><use href="#i-${name}"></use></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sprite=(i,cls='')=>`<div class="monster monster-${i} ${cls}" role="img" aria-label="${MONSTERS[i].name}"></div>`;
const DEFAULTS={mode:'mixed',timed:false,seconds:25,course:'ALL',scope:'all',groupIds:[],sfx:true,music:true,musicVolume:.12,sfxVolume:.35,voiceVolume:1};
let storageOK=true;
function read(key,fallback){try{const value=JSON.parse(localStorage.getItem(key));return value??fallback;}catch{storageOK=false;return fallback;}}
let settings={...DEFAULTS,...migrateAudioSettings(read('wordling-settings-v1',{}))};
let progress={captured:{},words:{},adventures:0,bestScore:0,...read('wordling-progress-v1',{})};
save();
function save(){try{localStorage.setItem('wordling-settings-v1',JSON.stringify(settings));localStorage.setItem('wordling-progress-v1',JSON.stringify(progress));}catch{storageOK=false;}}
let data,view='home',game=null,round=null,paused=false,score=0,sessionWords=[],timerId,remainingMs=0,lastTick=0,waitingForAudio=false,audioDeadline,sessionMode,voiceToken=0,speaking=false,modalPaused=false,park=null,parkReturnView='home',parkWasPaused=false;
let actionBusy=false,battleAction=null;
const sound=new IslandAudio(settings),speaker=new WordSpeaker(sound);
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>t.classList.remove('visible'),3600);}
function sfx(kind){sound.effect(kind);}
function stopPark(){park?.destroy();park=null;}
function header(gameHeader=false){return `<header class="${gameHeader?'game-header':''}"><button class="brand" data-action="home" aria-label="Wordling Island home"><span class="brand-icon">${icon('leaf')}</span><span class="brand-title">WORDLING<small>ISLAND · FIELD RANGERS</small></span></button><nav aria-label="Main menu"><button class="nav-button" data-action="park" title="Team Park">${icon('park')}Team Park</button><button class="nav-button" data-action="sound-settings" title="Music, effects, and voice settings">${icon('music')}Audio</button><button class="nav-button" data-action="records" title="Records">${icon('star')}Records</button><button class="nav-button" data-action="${gameHeader?'pause':'help'}" title="${gameHeader?'Pause':'How to play'}">${icon(gameHeader?'pause':'sparkle')}${gameHeader?'Pause':'Guide'}</button></nav></header>`;}
function pool(){if(settings.scope==='custom'&&!settings.groupIds.length)return [];return selectPool(data,settings.course,settings.scope==='all'?[]:settings.groupIds);}
function courseName(){if(settings.scope==='all')return settings.course==='ALL'?'CET + FET All words':`${settings.course} All words`;return `${settings.course==='ALL'?'CET + FET':settings.course} · Selected ${settings.groupIds.length} units`;}
function setChoice(action,value,label,active,extra=''){return `<button type="button" class="segment ${active?'active':''}" data-action="${action}" data-value="${value}" aria-pressed="${active}" ${extra}>${label}</button>`;}
function selectedSummary(){if(settings.scope==='all')return settings.course==='ALL'?'All CET Weeks + All FET Lessons':settings.course==='CET'?'All CET Weeks':'All FET Lessons';const selected=data.groups.filter(g=>settings.groupIds.includes(g.id));return selected.slice(0,3).map(g=>`${g.course} ${g.label}`).join(', ')+(selected.length>3?`, total ${selected.length} units`:'')||'No units selected';}
function unitPickerMarkup(){const courses=settings.course==='ALL'?['CET','FET']:[settings.course];return `<div class="course-picker"><div class="unit-actions"><button class="text-button ${settings.scope==='all'?'all-selected':''}" data-action="all-units">${settings.scope==='all'?'✓ ':''}All units</button><button class="text-button" data-action="clear-units">Clear</button><span class="word-count">${pool().length} words</span></div>${courses.map(course=>`<section class="course-unit-panel" aria-label="${course==='CET'?'CET Week selection':'FET Lesson selection'}"><div class="unit-panel-heading"><strong>${course==='CET'?'CET · Choose Weeks':'FET · Choose Lessons'}</strong><span>Multi-select</span><button class="text-button" data-action="course-all" data-course="${course}">Select all ${course}</button></div><div class="visible-unit-grid">${data.groups.filter(g=>g.course===course).map(g=>`<button class="unit-option ${settings.scope==='custom'&&settings.groupIds.includes(g.id)?'selected':''}" data-action="unit" data-value="${g.id}" aria-label="${course} ${g.label}" aria-pressed="${settings.scope==='custom'&&settings.groupIds.includes(g.id)}" title="${esc(g.topic||g.label)}">${g.label}${g.is_review?'<small>Review</small>':''}</button>`).join('')}</div></section>`).join('')}<p class="selection-summary" role="status">${esc(selectedSummary())}</p></div>`;}
function renderHome(openUnits=false){stopPark();view='home';sound.setScene('home');const groups=data.groups.filter(g=>settings.course==='ALL'||g.course===settings.course);const count=pool().length;app.innerHTML=`${header()}<main class="home"><div class="home-layout"><section class="home-copy"><div class="eyebrow">HEAR IT. LINK IT. CATCH IT.</div><h1>Hear the word.<br><span style="color:var(--green)">Build your team.</span></h1><p class="intro">Grab your Wordlink. Your mission starts now!<br>Hear the word. Send your beam. Build your team.</p><div class="setup">${!storageOK?'<div class="saved-warning">Saving is unavailable in this browser. You can still play. Use a regular browser window to keep your progress.</div>':''}<div class="setup-section"><div class="setup-label"><span class="step-num">1</span>Choose your mode</div><div class="segments">${setChoice('mode','choice',icon('sound')+'Listen & Pick',settings.mode==='choice')}${setChoice('mode','spell','Aa Spell It',settings.mode==='spell')}${setChoice('mode','mixed',icon('sparkle')+'Mixed',settings.mode==='mixed')}</div></div><div class="setup-section"><div class="setup-label"><span class="step-num">2</span>Choose your pace<span class="label-end">Find your pace</span></div><div class="time-line"><div class="segments">${setChoice('timed','false','∞ No timer',!settings.timed)}${setChoice('timed','true',icon('clock')+'Timed',settings.timed)}</div>${settings.timed?`<select class="small-select" id="seconds" aria-label="Seconds per word">${[15,25,40].map(n=>`<option value="${n}" ${settings.seconds===n?'selected':''}>Per word ${n} sec</option>`).join('')}</select>`:''}</div></div><div class="setup-section"><div class="setup-label"><span class="step-num">3</span>Choose your word course<span class="label-end">2026 FALL · G1</span></div><div class="course-segments">${[['ALL','CET + FET'],['CET','CET'],['FET','FET']].map(([value,label])=>`<button class="course-chip ${settings.course===value?'active':''}" data-action="course" data-value="${value}" aria-pressed="${settings.course===value}">${label}</button>`).join('')}</div>${unitPickerMarkup()}</div><button class="start-button" data-action="start" ${count<1?'disabled':''}><span>${icon('leaf')}Start mission</span>${icon('arrow')}</button><p class="setup-note">${count<1?'Choose at least one unit':`Mission pool: ${count} words · 5 monsters + 1 boss`}<br>Natural American English · Tap to enable audio</p></div></section><aside class="hero-column" aria-label="Meet the Wordling team"><div class="float-sticker">GEAR UP.<br>LINK UP!<span>READY FOR THE NEXT ENCOUNTER</span></div><div class="hero-scene"><div class="scene-top"><span class="dot"></span>FRONTIER RIDGE · RANGER OUTPOST</div>${sprite(0,'hero-monster')}${sprite(1,'hero-friend')}<span class="word-bubble">hello!</span><img class="hero-player" src="assets/ranger-v3.png" alt="Original field ranger with orange goggles, navy gear, and a laptop scanner"><div class="hero-caption"><span class="caption-icon">${icon('sparkle')}</span><div><strong>Your next teammate is out there.</strong><small>Every word powers your next move.</small></div></div></div><div class="hero-bottom"><span class="hero-feature">${icon('sound')}Listen & learn</span><span class="hero-feature">${icon('book')}Course words</span><span class="hero-feature">${icon('star')}Build your team</span></div></aside></div><footer class="island-line"><span><strong>Small words. Epic adventures.</strong> Every word makes your team stronger.</span><span class="footer-note">KCIS G1 · ${data.summary.unique_word_count} WORDS · MADE FOR LITTLE EXPLORERS</span></footer></main>`;}
function stopSpeech(){voiceToken++;speaker.stop();speaking=false;clearTimeout(audioDeadline);$('.audio-button')?.classList.remove('speaking');}
function speak(word,{first=false}={}){
 stopSpeech();const token=voiceToken,questionRound=round,isQuestionAudio=view==='game'&&round?.phase==='question'&&!paused&&word===round.card.english;
 if(first&&isQuestionAudio)waitingForAudio=true;
 const finish=()=>{if(token!==voiceToken)return;speaking=false;$('.audio-button')?.classList.remove('speaking');if(isQuestionAudio&&round===questionRound){waitingForAudio=false;lastTick=Date.now();}clearTimeout(audioDeadline);updateVoiceStatus();};
 speaker.play(word,{onstart:()=>{if(token!==voiceToken)return;speaking=true;$('.audio-button')?.classList.add('speaking');updateVoiceStatus('Playing American English…');},onend:finish,onerror:message=>{if(token!==voiceToken)return;finish();if(first&&isQuestionAudio)waitingForAudio=true;toast(message);}}).catch(()=>{finish();if(first&&isQuestionAudio)waitingForAudio=true;toast('Audio is unavailable. Tap the speaker to try again.');});
 audioDeadline=setTimeout(()=>{if(token===voiceToken&&first&&waitingForAudio){stopSpeech();toast('Audio is taking a little longer. Tap the speaker to retry. The timer is paused.');}},20000);
}
function updateVoiceStatus(message){const el=$('#voice-status');if(el)el.textContent=message||(speaker.fallback?'Using your device’s American voice. Reload to retry the recordings.':speaker.manifest?'Jenny · American English · Natural pace · All words loaded':'Loading American voice recordings…');}
function startGame(){stopBattleAction();if(!pool().length)return;window.scrollTo(0,0);save();sfx('start');stopSpeech();clearInterval(timerId);game=new Adventure(pool());score=0;sessionWords=[];sessionMode=settings.mode;paused=false;view='game';nextRound();timerId=setInterval(tick,120);}
function nextRound(){stopBattleAction();if(game.done)return finish();stopSpeech();const card=game.draw();let mode=sessionMode;if(mode==='mixed')mode=(game.correct%2===0?'choice':'spell');round={card,mode,phase:'question',options:makeOptions(card,game.pool),letters:scramble(card.english),selected:[],wrong:[],message:'',assisted:false,attempts:0,result:null};remainingMs=settings.seconds*1000;lastTick=Date.now();renderBattle();speak(card.english,{first:true});}
function currentMonster(){if(round?.result?.captured)return round.result.monster;return game.boss?5:game.stage;}
function renderBattle(){stopPark();view='game';sound.setScene(game.boss?'boss':'field');const mi=currentMonster(),m=MONSTERS[mi],isBoss=mi===5;const roundIndex=game.correct+1;app.innerHTML=`${header(true)}<main class="game-page"><div class="adventure-toolbar"><div class="journey-info"><strong>${isBoss?'Stormcrest Boss Battle':'Frontier Ridge Mission'}</strong><span>/ ${esc(courseName())}</span></div><div class="journey-path" aria-label="Mission progress">${MONSTERS.map((_,i)=>`${i?'<span class="path-line"></span>':''}<span class="path-node ${game.captures.includes(i)?'complete':i===mi?'current':''}">${game.captures.includes(i)?'✓':i===5?'★':i+1}</span>`).join('')}</div></div><section class="arena ${isBoss?'boss':''}" aria-label="Monster battle arena"><span class="location-label">${icon('leaf')}FRONTIER RIDGE · ${isBoss?'GUARDIAN ZONE':'CLEAR'}</span><div class="monster-status"><div class="monster-name"><strong>${m.name}</strong><span class="type-label">${isBoss?'BOSS · ':''}${m.type}</span></div><div class="hp-line"><span>${isBoss?'HP':'LINK'}</span><div class="hp-track" role="progressbar" aria-label="${isBoss?'Boss HP':'Capture link'}" aria-valuemin="0" aria-valuemax="${isBoss?3:1}" aria-valuenow="${isBoss?game.bossHp:round.phase==='success'?0:1}"><div class="hp-fill" style="width:${isBoss?game.bossHp/3*100:round.phase==='success'?0:100}%"></div></div></div><div class="hp-count">${isBoss?`HP ${game.bossHp} / 3 · One correct word = one hit`:'Wild monster · Waiting for your signal'}</div></div><div class="encounter-bubble" id="encounter-bubble">${isBoss?'Stormcrest appeared!<br>Land 3 word links to recruit the guardian.':`${m.name}  appeared in the tall grass!<br>Listen for the word, then fire your Wordlink!`}</div><div class="enemy-wrap ${isBoss?'boss-enemy':''} ${round.phase==='success'&&round.result?.captured?'captured':''}" id="enemy-wrap"><div class="enemy-shadow"></div>${sprite(mi,'enemy')}<span class="enemy-word ${round.phase==='question'?'':'revealed'}" id="enemy-word">${round.phase==='question'?'? '.repeat(Math.min(round.card.english.length,8)).trim():esc(round.card.english)}</span></div><div class="hero-actor" id="hero-actor"><img class="arena-player" src="assets/ranger-v3.png" alt="Original field ranger holding a Wordlink scanner"><div class="hero-action-sprite" aria-hidden="true"></div></div><div class="action-caption" id="action-caption" role="status" aria-live="polite"></div><div class="player-status"><strong>FIELD RANGER</strong><small>WORDLINK READY <span style="color:#75a979">● ● ●</span></small></div><div class="timer-badge" id="timer-badge">${icon(settings.timed?'clock':'leaf')}<span id="time-left">${settings.timed?Math.ceil(remainingMs/1000)+'s':'∞ No timer'}</span></div>${paused?pauseMarkup():''}</section><section class="computer-shell" aria-label="Wordlink terminal"><div class="computer-top"><span class="led"></span>WORDLINK · CAPTURE TERMINAL<span class="hardware-right">•••</span></div><div class="computer-screen" id="computer-screen">${questionMarkup()}</div></section><div class="game-bottom"><div class="game-stats"><span>${icon('book')}Caught <b id="capture-count">${game.captures.length}</b> / 6</span><span>${icon('star')}<b id="score-count">${score}</b> pts</span><span>${round.mode==='choice'?'Listen & Pick':'Spell It'}</span></div><span class="keyboard-note">Space to listen · ${round.mode==='choice'?'Press 1–4 to choose':'Type letters · Backspace to undo'} · Esc Pause</span></div></main>`;if(round.phase==='success')renderResult();else if(round.phase==='timeout')renderTimeout();}
function questionMarkup(){return `<div class="question-top"><div class="question-label"><button class="audio-button" data-action="replay" title="Listen again (Space)" aria-label="Listen to the word again">${icon('sound')}</button><div><strong>${round.mode==='choice'?'Which word did you hear?':'Spell the word you hear!'}</strong><small>${round.mode==='choice'?'Listen, then choose the word to fire your beam.':'Tap the letters in order. Tap a filled slot to undo. Include the hyphen, too.'}</small></div></div><div class="question-actions"><button class="help-button" data-action="hint">Word hint</button></div></div>${round.mode==='choice'?`<div class="choice-grid">${round.options.map((w,i)=>`<button class="answer-choice ${round.wrong.includes(w)?'wrong':''}" data-action="answer" data-word="${esc(w)}" ${round.wrong.includes(w)?'disabled':''}><span class="key">${i+1}</span>${esc(w)}</button>`).join('')}</div>`:spellMarkup()}<div class="feedback ${round.message.startsWith('Hint')?'good':''}" id="feedback" role="status" aria-live="polite">${esc(round.message)}</div>`;}
function spellMarkup(){return `<div class="spell-slots" aria-label="Your letter order">${[...round.card.english].map((_,i)=>round.selected[i]!==undefined?`<button class="letter-slot filled" data-action="unletter" data-index="${i}" aria-label="Remove slot ${i+1} letter ${round.letters.find(t=>t.id===round.selected[i]).letter}">${esc(round.letters.find(t=>t.id===round.selected[i]).letter)}</button>`:`<span class="letter-slot" aria-label="Slot ${i+1} empty slot"></span>`).join('')}</div><div class="letter-bank" aria-label="Letter tiles">${round.letters.map(t=>`<button class="letter-tile" data-action="letter" data-id="${t.id}" aria-label="Choose letter ${t.letter}" ${round.selected.includes(t.id)?'disabled':''}>${esc(t.letter)}</button>`).join('')}</div><div class="spell-tools"><button data-action="backspace">${icon('back')}Undo</button><button data-action="clear-letters">Clear letters</button></div>`;}
function updateQuestion(){const screen=$('#computer-screen');if(screen)screen.innerHTML=questionMarkup();if(speaking)$('.audio-button')?.classList.add('speaking');}
function submitAnswer(value){if(actionBusy||!round||round.phase!=='question'||paused||modal.open)return;const correct=value===round.card.english;round.attempts++;const result=game.answer(correct);round.result=result;
 if(!correct){round.message='Not quite! Listen again. You can do it!';if(round.mode==='choice')round.wrong.push(value);else round.selected=[];updateQuestion();runBattleAction('wrong',currentMonster());return;}
 round.phase='success';waitingForAudio=false;stopSpeech();const gained=round.assisted?50:round.attempts===1?100:70;score+=gained;
 const word=round.card.english;const record=progress.words[word]||{correct:0,attempts:0};record.correct++;record.attempts+=round.attempts;record.lastPracticed=new Date().toISOString();progress.words[word]=record;
 if(!sessionWords.find(c=>c.id===round.card.id))sessionWords.push(round.card);
 if(result.captured){const id=MONSTERS[result.monster].id;progress.captured[id]=(progress.captured[id]||0)+1;}save();
 const mi=result.captured?result.monster:5;const enemyWord=$('#enemy-word');enemyWord.textContent=word;enemyWord.classList.add('revealed');
 if(mi===5){$('.hp-fill').style.width=game.bossHp/3*100+'%';$('.hp-count').textContent=`HP ${game.bossHp} / 3 · ${game.bossHp?'Complete  '+game.bossHp+' more words':'Recruited to your team!'}`;const track=$('.hp-track');track.setAttribute('aria-valuenow',game.bossHp);}
 else {$('.hp-fill').style.width='0%';$('.hp-track').setAttribute('aria-valuenow','0');}
 $('#score-count').textContent=score;$('#capture-count').textContent=game.captures.length;
 $('#encounter-bubble').innerHTML=result.captured?`${MONSTERS[mi].name}  received your signal!<br>A new teammate joined your adventure!`:'Direct hit! The guardian lost 1 HP.<br>Keep it up. One step closer to a new teammate!';
 renderResult(gained);runBattleAction(result.captured?'capture':'hit',mi);
}
function renderResult(gained=round.assisted?50:round.attempts===1?100:70){const r=round.result;$('#computer-screen').innerHTML=`<div class="result-row" role="status"><div><div class="eyebrow">${r.captured?'NEW FRIEND CAPTURED!':'GREAT SIGNAL!'}</div><div class="result-word">${esc(round.card.english)}<small>${esc(round.card.pos_zh)} · ${esc(round.card.meaning_zh)}</small></div><p>${r.captured?`Caught ${MONSTERS[r.monster].name}!`:`Boss HP −1. Remaining: ${game.bossHp}  HP.`} +${gained} pts</p></div><button class="next-button" data-action="next" ${actionBusy?'disabled':''}>${r.done?'View mission results':r.captured&&game.boss?'Face the boss':r.captured?'Next encounter':'Next boss round'}${icon('arrow')}</button></div>`;}

function lockBattleControls(value){$('#computer-screen')?.setAttribute('aria-busy',String(value));document.querySelectorAll('#computer-screen button').forEach(b=>{if(value){if(!b.disabled){b.dataset.actionLocked='true';b.disabled=true;}}else if(b.dataset.actionLocked){delete b.dataset.actionLocked;b.disabled=false;}});}
function stopBattleAction(){if(!battleAction)return;battleAction.cancel();battleAction=null;actionBusy=false;lockBattleControls(false);if(round?.phase==='success'&&round.result?.captured)$('#enemy-wrap')?.classList.add('captured');}
async function runBattleAction(kind,index){stopBattleAction();stopSpeech();if(kind==='wrong')waitingForAudio=true;actionBusy=true;lockBattleControls(true);const activeRound=round,action=battleAction=new BattleAction($('.arena'),sound,speaker);try{await action.play(kind,index,round.result?.done);}catch{toast('Battle move finished. Ready for your next word!');}if(battleAction!==action||round!==activeRound)return;action.clean();battleAction=null;actionBusy=false;lockBattleControls(false);lastTick=Date.now();if(kind==='wrong'&&view==='game'&&!paused&&!modal.open)speak(round.card.english,{first:true});}

function confetti(target){const colors=['#f8dd88','#b7d6a8','#e8b6c9','#c6b6e2'];target.insertAdjacentHTML('beforeend',`<div class="sparkles">${Array.from({length:20},(_,i)=>`<i style="left:${45+Math.random()*40}%;top:${10+Math.random()*30}%;background:${colors[i%4]};animation-delay:${Math.random()*.4}s;transform:rotate(${i*13}deg)"></i>`).join('')}</div>`);}
function tick(){const now=Date.now(),elapsed=now-lastTick;lastTick=now;if(view!=='game'||!round||round.phase!=='question'||paused||actionBusy||modal.open||waitingForAudio||!settings.timed)return;remainingMs=Math.max(0,remainingMs-elapsed);const left=$('#time-left'),badge=$('#timer-badge');if(left)left.textContent=Math.ceil(remainingMs/1000)+'s';badge?.classList.toggle('urgent',remainingMs<6000);if(remainingMs===0)timeout();}
function timeout(){round.phase='timeout';round.attempts++;game.answer(false);stopSpeech();sfx('wrong');waitingForAudio=false;$('#enemy-word').textContent=round.card.english;$('#enemy-word').classList.add('revealed');renderTimeout();toast('Boss HP stays the same. Your caught monsters are safe.');}
function renderTimeout(){$('#computer-screen').innerHTML=`<div class="result-row"><div><div class="eyebrow">TAKE A LITTLE BREATH</div><div class="result-word">${esc(round.card.english)}<small>${esc(round.card.meaning_zh)}</small></div><p>Time is up! Your team is safe. Listen, remember the word, and try another round.</p></div><button class="next-button" data-action="next">Try another word${icon('arrow')}</button></div>`;}
function pauseMarkup(){return `<div class="pause-cover"><div class="brand-icon">${icon('leaf')}</div><h2>Mission paused</h2><p>Take a break. Your team will wait for you.</p><button class="next-button" data-action="resume">Resume mission${icon('arrow')}</button><button class="help-button" data-action="confirm-home">Back to start</button></div>`;}
function pause(){if(view!=='game'||paused)return;stopBattleAction();paused=true;stopSpeech();$('.arena').insertAdjacentHTML('beforeend',pauseMarkup());}
function resume(){if(view!=='game')return;paused=false;$('.pause-cover')?.remove();lastTick=Date.now();if(waitingForAudio&&round.phase==='question')speak(round.card.english,{first:true});}
function openModal(content){stopBattleAction();if(view==='game'&&!paused){modalPaused=true;paused=true;stopSpeech();}else modalPaused=false;modal.innerHTML=content;modal.showModal();}
function modalHeading(title,description=''){return `<div class="modal-heading"><div><h2>${title}</h2>${description?`<p>${description}</p>`:''}</div><button class="close-button" data-action="close-modal" aria-label="Close">${icon('close')}</button></div>`;}
function showCollection(){openModal(modalHeading('Monster field guide',`Found ${Object.keys(progress.captured).length} / 6 species found · Saved on this device`)+`<div class="collection-grid">${MONSTERS.map((m,i)=>`<article class="collection-card ${progress.captured[m.id]?'':'locked'}"><span class="caught-mark">${progress.captured[m.id]?icon('check')+' Caught '+progress.captured[m.id]+' times':'Not caught'}</span>${sprite(i)}<small>NO. 00${i+1} · ${m.type}</small><h3>${m.name}</h3><small>${m.en}</small><p>${m.description}</p></article>`).join('')}</div>`);}
function showRecords(){const words=Object.keys(progress.words).sort();openModal(modalHeading('Your mission record','Your learning record · Saved in this browser')+`<div class="records-summary"><div class="record-number"><strong>${words.length}</strong>Words practiced</div><div class="record-number"><strong>${progress.adventures}</strong>Missions cleared</div><div class="record-number"><strong>${progress.bestScore}</strong>Best score</div></div><div class="word-records">${words.length?words.map(w=>`<span>${esc(w)} <small style="color:#94a186">×${progress.words[w].correct}</small></span>`).join(''):'<p class="empty-note">Your first word starts here. Catch a monster to add a word to your record!</p>'}</div>`);}
function showSoundSettings(){openModal(modalHeading('Audio settings','Set music, effects, and voice levels separately.')+`<div class="audio-settings"><div class="voice-setting"><span class="voice-badge">US</span><div><strong>Jenny · Natural American English</strong><p>Clear American English at a natural pace.</p><small id="voice-status"></small></div><button class="secondary-button" data-action="preview-voice">${icon('sound')}Preview flower</button></div>${[['music','Adventure music','Original adventure score · Soft background mix','musicVolume'],['sfx','Sound effects','Beams, battle moves, letters, and team interactions','sfxVolume']].map(([key,label,note,volume])=>`<div class="audio-control"><div class="audio-control-top"><div><strong>${label}</strong><small>${note}</small></div><button class="audio-toggle ${settings[key]?'on':''}" data-action="toggle-audio" data-setting="${key}" aria-pressed="${settings[key]}" aria-label="${label} toggle">${settings[key]?'On':'Off'}</button></div><label class="volume-line" for="${volume}"><span>Volume</span><input id="${volume}" type="range" min="0" max="100" value="${Math.round(settings[volume]*100)}" data-volume="${volume}" aria-label="${label} volume"><output id="${volume}-value">${Math.round(settings[volume]*100)}%</output></label></div>`).join('')}<div class="audio-control"><label class="volume-line" for="voiceVolume"><span>Voice volume</span><input id="voiceVolume" type="range" min="15" max="100" value="${Math.round(settings.voiceVolume*100)}" data-volume="voiceVolume" aria-label="Voice volume"><output id="voiceVolume-value">${Math.round(settings.voiceVolume*100)}%</output></label></div><p class="audio-hint">Voice comes first: music fades out during speech and returns softly afterward. Effects also become quieter. Audio starts after your first tap; leaving the tab pauses it.</p></div>`);updateVoiceStatus();speaker.ready.then(()=>updateVoiceStatus());}
function help(){openModal(modalHeading('Ranger field guide','Turn on your sound. Let’s start the mission!')+`<div class="help-content"><h3>Choose your Weeks or Lessons</h3><p>Pick CET Weeks or FET Lessons on the start screen. You can select more than one unit. Tap All units to use the full course. CET Week 1–2 is one unit.</p><h3>Listen & Pick / Spell It</h3><p>Listen to Jenny, then choose one of four words or tap the letters in order. Use every letter, including repeated letters and the hyphen in grown-up. Tap a filled slot to remove a letter. You can always try again.</p><h3>Battle moves</h3><p>Get a word right to fire your Wordlink beam! A normal monster joins your team after one hit. The boss takes three hits. A wrong answer makes the monster strike back. Your shield blocks the attack, then the word plays again. The timer pauses during battle moves.</p><h3>Boss battles and the timer</h3><p>Catch five monsters, then face Stormcrest! The boss has 3 HP. Get three words right to catch it. Choose no timer, or 15, 25, or 40 seconds per word. The timer starts after the first word is spoken. Opening settings, the park, or another tab pauses the game.</p><h3>Team Park</h3><p>Your caught monsters roam around the Team Park. Tap a monster to say hello. Rally calls the team together. Snack time brings them to the picnic spot. Your current battle is saved while you visit.</p><h3>Audio and saved progress</h3><p>Open Audio to change music, effects, and voice levels. Music goes quiet during speech so every word stays clear. Your team and learning record are saved in this browser.</p><h3>Need a hint?</h3><p>Tap the speaker to hear the word again, or tap Word hint. Earn 100 points on your first try, 70 after a retry, or 50 with a hint.</p></div>`);}
function showPark(){if(view==='park')return;stopBattleAction();parkReturnView=view;parkWasPaused=paused;if(view==='game')paused=true;stopSpeech();stopPark();view='park';sound.setScene('park');window.scrollTo(0,0);const owned=MONSTERS.map((m,index)=>({...m,index})).filter(m=>progress.captured[m.id]>0);app.innerHTML=`${header()}<main class="park-page"><div class="park-heading"><div><div class="eyebrow">YOUR TEAM. YOUR NEXT MISSION.</div><h1>Your <span>Team Park</span></h1><p>Train together. Explore together. Meet your whole team.</p></div><button class="secondary-button" data-action="park-back">${icon('back')}${parkReturnView==='game'?'Back to battle':'Back to start'}</button></div><div class="park-toolbar"><div class="park-count">${icon('leaf')}<strong>${owned.length} / 6</strong> species recruited</div><div class="park-actions"><button data-action="park-gather" ${owned.length?'':'disabled'}>${icon('sparkle')}Rally</button><button data-action="park-feed" ${owned.length?'':'disabled'}>Snack time</button><button data-action="collection">${icon('book')}Field guide</button></div></div><section class="park-world" id="park-world" aria-label="Team park with freely roaming caught monsters"><div class="park-sign">TEAM PARK<small>RANGER TEAM PARK</small></div><div class="park-weather">☀ Clear skies · Patrol in progress</div><div class="park-picnic" aria-hidden="true"><span>✦</span><i></i><i></i><i></i></div>${owned.map(m=>`<button class="park-creature" data-action="pet-monster" data-park-id="${m.id}" aria-label="Greet ${m.name}"><span class="park-shadow"></span><span class="park-face">${sprite(m.index,'park-sprite')}</span><span class="park-monster-name">${m.name}</span><span class="park-heart" aria-hidden="true">✦</span></button>`).join('')}${owned.length?'':`<div class="empty-park"><span class="brand-icon">${icon('leaf')}</span><h2>Your first teammate belongs here.</h2><p>Catch your first monster in a word battle!</p><button class="next-button" data-action="park-back">Start your mission${icon('arrow')}</button></div>`}<div class="park-activity" id="park-activity" role="status">${owned.length?'Your team is on patrol. Tap a monster to say hello!':'Every word brings a new encounter.'}</div></section><div class="park-bottom"><section class="park-detail" id="park-detail">${owned.length?parkDetail(owned[0].index):'<div><strong>Ready to recruit your first teammate?</strong><p>Your team stays in this browser. Come back here after your next adventure.</p></div>'}</section><div class="park-residents" aria-label="Team roster">${MONSTERS.map((m,i)=>`<button class="resident-token ${progress.captured[m.id]?'':'locked'}" data-action="park-focus" data-index="${i}" title="${progress.captured[m.id]?m.name:'Not caught '+m.name}" aria-label="${progress.captured[m.id]?'Meet':'Not caught'} ${m.name}">${sprite(i)}<small>${progress.captured[m.id]?'✓':'?'}</small></button>`).join('')}</div></div><p class="park-save-note">Only caught monsters appear here. Your team is saved in this browser.</p></main>`;park=new MonsterPark($('#park-world'),owned,{onPet:c=>{sound.cry(c.index);speak('@pet');$('#park-detail').innerHTML=parkDetail(c.index);$('#park-activity').textContent=`${MONSTERS[c.index].name} says hello. Ready for the next mission!`;}});}
function parkDetail(index){const m=MONSTERS[index];return `${sprite(index,'park-detail-sprite')}<div><small>${m.type} · ${m.en}</small><h2>${m.name}<span>Caught ${progress.captured[m.id]||0} times</span></h2><p>${m.description}</p></div>`;}
function backFromPark(){stopSpeech();stopPark();if(parkReturnView==='game'&&game){paused=parkWasPaused;renderBattle();lastTick=Date.now();if(!paused&&waitingForAudio&&round.phase==='question')speak(round.card.english,{first:true});}else renderHome();}
function confirmHome(){if(view!=='game')return renderHome();if(!paused)pause();openModal(modalHeading('Return to base?','Your caught monsters and word record will stay. This adventure will end.')+`<div class="finish-actions"><button class="secondary-button" data-action="close-modal">Keep playing</button><button class="next-button" data-action="leave-game">Back to start${icon('arrow')}</button></div>`);}
function finish(){stopPark();sound.setScene('home');window.scrollTo(0,0);stopSpeech();clearInterval(timerId);view='finish';progress.adventures++;progress.bestScore=Math.max(progress.bestScore,score);save();app.innerHTML=`${header()}<main class="finish-page"><div class="finish-eyebrow">ADVENTURE COMPLETE</div><h1>Mission complete. Team assembled!</h1><p>You and Stormcrest cleared the word challenge!<br>Keep learning. Your next adventure is waiting!</p><div class="finish-monsters">${MONSTERS.map((m,i)=>sprite(i)).join('')}</div><div class="records-summary"><div class="record-number"><strong>${score}</strong>Mission score</div><div class="record-number"><strong>6 / 6</strong>Teammates recruited</div><div class="record-number"><strong>${Math.round(game.correct/game.attempts*100)}%</strong>Accuracy</div></div>${!storageOK?'<p class="saved-warning">Saving is unavailable. Keep this page open to retain your team.</p>':''}<div class="finish-actions"><button class="secondary-button" data-action="park">Visit Team Park</button><button class="secondary-button" data-action="home">Change units</button><button class="next-button" data-action="start">Play again${icon('arrow')}</button></div><section class="learned-list"><h3>Mission words · Tap a speaker to listen again</h3><div class="learned-chips">${sessionWords.map(c=>`<span class="learned-chip">${esc(c.english)}<small>${esc(c.meaning_zh)}</small><button data-action="speak-word" data-word="${esc(c.english)}" aria-label="Listen to ${esc(c.english)}">${icon('sound')}</button></span>`).join('')}</div></section></main>`;}
function chooseLetter(id){if(actionBusy||round?.phase!=='question'||paused||round.mode!=='spell'||round.selected.includes(id))return;sfx('letter');round.selected.push(id);round.message='';updateQuestion();if(round.selected.length===round.letters.length){const word=round.selected.map(n=>round.letters.find(t=>t.id===n).letter).join('');submitAnswer(word);}}
function dispatch(action,target){if(actionBusy&&['answer','letter','unletter','backspace','clear-letters','replay','hint','next'].includes(action))return;switch(action){
 case'mode':settings.mode=target.dataset.value;save();renderHome();break;
 case'timed':settings.timed=target.dataset.value==='true';save();renderHome();break;
 case'course':settings.course=target.dataset.value;settings.scope='all';settings.groupIds=[];save();renderHome();break;
 case'unit':{const id=target.dataset.value;if(settings.scope==='all'){settings.groupIds=[];settings.scope='custom';}if(settings.groupIds.includes(id))settings.groupIds=settings.groupIds.filter(n=>n!==id);else settings.groupIds.push(id);save();renderHome(true);break;}
 case'course-all':settings.scope='custom';settings.groupIds=data.groups.filter(g=>g.course===target.dataset.course).map(g=>g.id);save();renderHome();break;
 case'all-units':settings.scope='all';settings.groupIds=[];save();renderHome(true);break;
 case'clear-units':settings.scope='custom';settings.groupIds=[];save();renderHome(true);break;
 case'start':startGame();break;
 case'answer':submitAnswer(target.dataset.word);break;
 case'letter':chooseLetter(Number(target.dataset.id));break;
 case'unletter':if(round?.phase==='question'&&!paused){round.selected.splice(Number(target.dataset.index),1);updateQuestion();}break;
 case'backspace':if(round?.phase==='question'&&!paused){round.selected.pop();updateQuestion();}break;
 case'clear-letters':if(round?.phase==='question'&&!paused){round.selected=[];updateQuestion();}break;
 case'replay':if(!paused)speak(round.card.english,{first:waitingForAudio});break;
 case'speak-word':speak(target.dataset.word);break;
 case'hint':if(round?.phase==='question'&&!paused){round.assisted=true;round.message=`Hint: ${round.card.english} — ${round.card.meaning_zh} (50 points with a hint)`;$('#enemy-word').textContent=round.card.english;$('#enemy-word').classList.add('revealed');updateQuestion();}break;
 case'next':if(!paused&&round.phase!=='question')nextRound();break;
 case'pause':pause();break;
 case'resume':resume();break;
 case'home':if(view==='game')confirmHome();else if(view==='park'&&parkReturnView==='game'){backFromPark();confirmHome();}else{stopSpeech();window.scrollTo(0,0);renderHome();}break;
 case'confirm-home':confirmHome();break;
 case'leave-game':modal.close();clearInterval(timerId);stopSpeech();paused=false;game=null;round=null;window.scrollTo(0,0);renderHome();break;
 case'park':showPark();break;
 case'park-back':backFromPark();break;
 case'park-gather':park?.gather();sfx('start');$('#park-activity').textContent='Rally up! Your team is heading this way.';break;
 case'park-feed':park?.feed();sfx('feed');$('#park-activity').textContent='Snack time! Your team is heading to the picnic spot.';break;
 case'pet-monster':park?.pet(target.dataset.parkId);break;
 case'park-focus':{const i=Number(target.dataset.index);if(progress.captured[MONSTERS[i].id])park?.pet(MONSTERS[i].id);else toast('Catch  '+MONSTERS[i].name+' to recruit it to your Team Park!');break;}
 case'sound-settings':showSoundSettings();break;
 case'preview-voice':speak('flower');break;
 case'toggle-audio':{const key=target.dataset.setting;settings[key]=!settings[key];sound.activate();sound.update();save();target.classList.toggle('on',settings[key]);target.setAttribute('aria-pressed',settings[key]);target.textContent=settings[key]?'On':'Off';if(key==='sfx'&&settings.sfx)sfx('pet');break;}
 case'collection':showCollection();break;
 case'records':showRecords();break;
 case'help':help();break;
 case'close-modal':stopSpeech();modal.close();break;
 case'sfx':settings.sfx=!settings.sfx;sound.update();save();target.textContent=(settings.sfx?'Off':'On')+'battle sounds';break;
}}
document.addEventListener('pointerdown',()=>sound.activate(),{once:true});
document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(!target||target.disabled)return;if(modal.open&&!modal.contains(target))return;dispatch(target.dataset.action,target);});
document.addEventListener('input',e=>{const key=e.target.dataset.volume;if(!key)return;settings[key]=Number(e.target.value)/100;sound.update();save();$('#'+key+'-value').textContent=e.target.value+'%';});
document.addEventListener('change',e=>{if(e.target.id==='seconds'){settings.seconds=Number(e.target.value);save();}});
modal.addEventListener('close',()=>{stopSpeech();if(modalPaused&&view==='game'){paused=false;lastTick=Date.now();if(waitingForAudio&&round.phase==='question')speak(round.card.english,{first:true});}modalPaused=false;});
document.addEventListener('keydown',e=>{if(view!=='game'||modal.open||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.key==='Escape'){e.preventDefault();paused?resume():pause();return;}if(paused||actionBusy)return;if(e.code==='Space'){e.preventDefault();if(round.phase==='question')speak(round.card.english,{first:waitingForAudio});return;}if(round.phase!=='question'){if(e.key==='Enter'){e.preventDefault();nextRound();}return;}if(round.mode==='choice'&&/^[1-4]$/.test(e.key)){e.preventDefault();const word=round.options[Number(e.key)-1];if(!round.wrong.includes(word))submitAnswer(word);}else if(round.mode==='spell'){if(e.key==='Backspace'){e.preventDefault();round.selected.pop();updateQuestion();}else if(/^[a-zA-Z-]$/.test(e.key)){e.preventDefault();const tile=round.letters.find(t=>t.letter===e.key.toLowerCase()&&!round.selected.includes(t.id));if(tile)chooseLetter(tile.id);}}});
document.addEventListener('visibilitychange',()=>{sound.setVisible(!document.hidden);if(document.hidden){stopSpeech();if(view==='game'&&!modal.open)pause();}});
try{const response=await fetch('data/vocabulary.json');if(!response.ok)throw Error('Word data could not load');data=await response.json();if(!data.cards?.length||!data.groups?.length)throw Error('Word data is incomplete');settings.groupIds=settings.groupIds.filter(id=>data.groups.some(g=>g.id===id));if(!['ALL','CET','FET'].includes(settings.course))settings.course='ALL';if(!['choice','spell','mixed'].includes(settings.mode))settings.mode='mixed';if(![15,25,40].includes(settings.seconds))settings.seconds=25;renderHome();}catch(e){app.innerHTML=`<main class="error-box"><h1>Word data is not ready</h1><p>Open the game from its website address, then reload the page.</p><p>${esc(e.message)}</p><button class="next-button" onclick="location.reload()">Reload</button></main>`;}
